const $ = s => document.querySelector(s);
const state={user:null,guilds:[],guild:null,channel:null,dm:null,socket:null,members:[],friends:[],notifications:[],notificationListener:false,viewedUser:null,voice:null,voiceRoster:{},search:'',profileAvatar:'',incomingCall:null};
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let soundEnabled=localStorage.getItem('brasa_sounds')!=='off',soundContext;
$('#soundToggle').setAttribute('aria-pressed',String(soundEnabled));$('#soundToggle').title=soundEnabled?'Desativar sons':'Ativar sons';$('#soundToggle').setAttribute('aria-label',$('#soundToggle').title);
function playUiSound(kind='click'){if(!soundEnabled)return;try{const Audio=window.AudioContext||window.webkitAudioContext;soundContext??=new Audio();if(soundContext.state==='suspended')soundContext.resume();const osc=soundContext.createOscillator(),gain=soundContext.createGain(),now=soundContext.currentTime;osc.type='sine';osc.frequency.setValueAtTime(kind==='send'?660:kind==='toggle'?510:kind==='notify'?740:420,now);osc.frequency.exponentialRampToValueAtTime(kind==='send'?880:kind==='toggle'?690:kind==='notify'?960:520,now+.055);gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(kind==='notify'?.045:.035,now+.008);gain.gain.exponentialRampToValueAtTime(.0001,now+.075);osc.connect(gain);gain.connect(soundContext.destination);osc.start(now);osc.stop(now+.08)}catch{}}
document.addEventListener('click',event=>{const target=event.target.closest('button,[role="button"],a');if(!target||target.disabled||target.id==='soundToggle'||target.matches('.send,.voice-channel-entry .channel-link,.end-call,#dockLeaveCall,#logoutBtn'))return;playUiSound(target.matches('.primary.auth-submit')?'send':'click')},true);
$('#soundToggle').addEventListener('click',()=>{soundEnabled=!soundEnabled;localStorage.setItem('brasa_sounds',soundEnabled?'on':'off');const button=$('#soundToggle');button.setAttribute('aria-pressed',String(soundEnabled));button.title=soundEnabled?'Desativar sons':'Ativar sons';button.setAttribute('aria-label',button.title);if(soundEnabled)playUiSound('toggle')});
async function api(url,options={}){const res=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})},body:options.body?JSON.stringify(options.body):undefined});let data={};try{data=await res.json()}catch{}if(!res.ok)throw new Error(data.error||'Algo deu errado.');return data}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.add('hidden'),3200)}
function initials(name){return String(name||'?').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'?'}
function lucide(name){const paths={hash:'<path d="M4 9h16M4 15h16M10 3 8 21M16 3l-2 18"/>',volume:'<path d="M11 5 6 9H3v6h3l5 4z"/><path d="M15.5 8.5a5 5 0 0 1 0 7M18.5 5.5a9 9 0 0 1 0 13"/>',plus:'<path d="M12 5v14M5 12h14"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="10" cy="7" r="4"/><path d="M20 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',flame:'<path d="M8.5 14.5A5.5 5.5 0 0 0 19 12c0-3.5-2-5.5-4-8-.5 3-2 4-3 4.5C11.5 5 9 3 9 3 9 7 5 9.5 5 13a7 7 0 0 0 14 0"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-6v-7h-4v7H4a1 1 0 0 1-1-1z"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.7a8 8 0 0 1-1.6.9L16 21h-3l-.3-2.2a8 8 0 0 1-1.6-.9l-1.7.7L8 16.2l1.4-1.1a8 8 0 0 1 0-1.8L8 12.2l1.4-2.4 1.7.7a8 8 0 0 1 1.6-.9L13 7h3l.3 2.2a8 8 0 0 1 1.6.9l1.7-.7 1.4 2.4-1.4 1.1a8 8 0 0 1-.2 2.1Z"/>',message:'<path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8A8.5 8.5 0 0 1 8.7 3.9a8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8z"/>',camera:'<path d="m15 10 5-3v10l-5-3"/><rect x="3" y="6" width="12" height="12" rx="2"/>',monitor:'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8M12 17v4"/>',mic:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>',phone:'<path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.4 19.4 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7l.4 2.8a2 2 0 0 1-.6 1.7L7 10.1a16 16 0 0 0 6 6l1.9-1.9a2 2 0 0 1 1.7-.6l2.8.4a2 2 0 0 1 1.6 1.9z"/>',volumeX:'<path d="M11 5 6 9H3v6h3l5 4zM22 9l-6 6M16 9l6 6"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.plus}</svg>`}
function avatar(user,online=false){return `<div class="avatar ${online?'online':''}">${user?.avatar?`<img src="${escapeHtml(user.avatar)}" alt="">`:escapeHtml(initials(user?.displayName||user?.username))}</div>`}
function friendRelationship(userId){return state.friends.find(row=>row.user.id===userId)}
function setProfileAvatar(target,user){target.innerHTML=user?.avatar?`<img src="${escapeHtml(user.avatar)}" alt="">`:escapeHtml(initials(user?.displayName||user?.username))}
function showUserCard(user){if(!user?.id)return;state.viewedUser=user;$('#userCardName').textContent=user.displayName||'Usuário';$('#userCardDisplayName').textContent=user.displayName||'Usuário';$('#userCardHandle').textContent=user.username?`@${user.username}`:'Membro do Brasa';setProfileAvatar($('#userCardAvatar'),user);const relation=friendRelationship(user.id),add=$('#userCardAdd');add.classList.toggle('hidden',user.id===state.user?.id||relation?.status==='accepted');add.disabled=relation?.direction==='outgoing'&&relation.status==='pending';add.textContent=add.disabled?'Pedido enviado':relation?.direction==='incoming'&&relation.status==='pending'?'Aceitar pedido':'Adicionar amigo';$('#userCardStatus').textContent=user.id===state.user?.id?'Este é o seu perfil.':relation?.status==='accepted'?'Vocês já são amigos.':relation?.status==='pending'?(relation.direction==='incoming'?'Enviou um pedido para você.':'Pedido de amizade enviado.'):'Ainda não são amigos.';$('#userCardDialog').showModal()}
function showUserDetails(user=state.viewedUser){if(!user)return;$('#userCardDialog').close();$('#userDetailName').textContent=user.displayName||'Usuário';$('#userDetailDisplayName').textContent=user.displayName||'Usuário';$('#userDetailHandle').textContent=user.username?`@${user.username}`:'Membro do Brasa';setProfileAvatar($('#userDetailAvatar'),user);const member=state.members.find(item=>item.id===user.id);$('#userDetailMembership').textContent=member?`Membro de ${state.guild?.name||'esta comunidade'} · ${member.state==='online'?'Online':'Offline'}`:'Perfil de usuário do Brasa';const relation=friendRelationship(user.id),add=$('#userDetailAdd');add.classList.toggle('hidden',user.id===state.user?.id||relation?.status==='accepted');add.disabled=relation?.direction==='outgoing'&&relation.status==='pending';add.textContent=add.disabled?'Pedido enviado':relation?.direction==='incoming'&&relation.status==='pending'?'Aceitar pedido':'Adicionar amigo';$('#userDetailDialog').showModal()}
async function requestFriendFromProfile(){const user=state.viewedUser;if(!user)return;try{await api('/api/friends',{method:'POST',body:{userId:user.id}});await loadFriends();$('#userCardDialog').close();if($('#userDetailDialog').open)$('#userDetailDialog').close();toast('Pedido de amizade atualizado.')}catch(error){toast(error.message)}}
$('#userCardClose').addEventListener('click',()=>$('#userCardDialog').close());$('#userCardView').addEventListener('click',()=>showUserDetails());$('#userCardAdd').addEventListener('click',requestFriendFromProfile);$('#userDetailClose').addEventListener('click',()=>$('#userDetailDialog').close());$('#userDetailAdd').addEventListener('click',requestFriendFromProfile);$('#userDetailMessage').addEventListener('click',async()=>{const user=state.viewedUser;$('#userDetailDialog').close();await openDmWithUser(user)});
function showAuth(register=false){$('#authScreen').classList.remove('hidden');$('#layout').classList.add('hidden');$('#authTitle').innerHTML=register?'Crie sua conta':'Bem-vindo <em>de volta!</em>';$('#authSubtitle').textContent=register?'Crie seu usuário e senha para entrar na comunidade.':'Faça login para continuar na sua comunidade.';$('#authSubmit span').textContent=register?'Criar conta':'Entrar';$('#authSwitchText').textContent=register?'Já tem uma conta?':'Não tem uma conta?';$('#authSwitch').textContent=register?'Entrar':'Criar conta';$('#displayNameField').classList.toggle('hidden',!register);$('#authForm').classList.toggle('register-mode',register);$('#authCard').classList.toggle('register-mode',register);$('#forgotPassword').classList.toggle('hidden',register);$('#authForm').dataset.mode=register?'register':'login';$('#authError').textContent='';$('#authPassword').value='';$('#authPassword').type='password';$('#authPassword').autocomplete=register?'new-password':'current-password';$('#passwordToggle').setAttribute('aria-label','Mostrar senha');$('#passwordToggle').title='Mostrar senha'}
$('#authSwitch').addEventListener('click',()=>showAuth($('#authForm').dataset.mode!=='register'));
const rememberedUsername=localStorage.getItem('brasa_remembered_username');if(rememberedUsername){$('#authForm').elements.username.value=rememberedUsername;$('#rememberMe').checked=true}
$('#rememberMe').addEventListener('change',()=>{if($('#rememberMe').checked){const username=$('#authForm').elements.username.value.trim();if(username)localStorage.setItem('brasa_remembered_username',username)}else localStorage.removeItem('brasa_remembered_username')});$('#authForm').elements.username.addEventListener('input',e=>{if($('#rememberMe').checked)localStorage.setItem('brasa_remembered_username',e.target.value.trim())});
$('#passwordToggle').addEventListener('click',()=>{const input=$('#authPassword'),show=input.type==='password';input.type=show?'text':'password';$('#passwordToggle').setAttribute('aria-label',show?'Ocultar senha':'Mostrar senha');$('#passwordToggle').title=show?'Ocultar senha':'Mostrar senha';input.focus()});
$('#forgotPassword').addEventListener('click',()=>{$('#authError').textContent='A recuperação por e-mail ainda não foi configurada. Peça ao administrador do Brasa para redefinir sua senha.'});
function setAuthTheme(light){document.body.classList.toggle('auth-light',light);$('#themeModeText').textContent=light?'Modo claro':'Modo escuro';$('#themeToggle').setAttribute('aria-pressed',String(light));localStorage.setItem('brasa_auth_theme',light?'light':'dark')}
setAuthTheme(localStorage.getItem('brasa_auth_theme')==='light');$('#themeToggle').addEventListener('click',()=>setAuthTheme(!document.body.classList.contains('auth-light')));
$('#authForm').addEventListener('submit',async e=>{e.preventDefault();const form=new FormData(e.currentTarget);const mode=e.currentTarget.dataset.mode;try{const data=await api(`/api/${mode}`,{method:'POST',body:{username:form.get('username'),password:form.get('password'),displayName:form.get('displayName')}});state.user=data.user;await bootApp();await acceptInvite()}catch(err){$('#authError').textContent=err.message}});
async function bootApp(){if(!state.user){try{const data=await api('/api/session');state.user=data.user}catch{showAuth();return}}$('#authScreen').classList.add('hidden');$('#layout').classList.remove('hidden');renderOwnProfile();state.socket=io();state.socket.on('presence',updatePresence);state.socket.on('guild:voice-roster',data=>{state.voiceRoster[data.guildId]=Object.fromEntries(data.channels.map(c=>[c.channelId,c.participants]));if(state.guild?.id===data.guildId)renderChannels(state.guild.channels.filter(c=>c.type==='text'),state.guild.channels.filter(c=>c.type==='voice'))});state.socket.on('friends:update',loadFriends);state.socket.on('guild:updated',guild=>{const current=state.guilds.find(item=>item.id===guild.id);if(current)Object.assign(current,guild);if(state.guild?.id===guild.id){Object.assign(state.guild,guild);$('#communityCardName').textContent=guild.name;renderGuildCover();renderGuildRail()}toast('Comunidade atualizada.')});state.socket.on('guild:channel-added',channel=>{const guild=state.guilds.find(item=>item.id===channel.guildId);if(!guild)return;if(!guild.channels.some(item=>item.id===channel.id))guild.channels.push(channel);if(state.guild?.id===channel.guildId)renderChannels(state.guild.channels.filter(c=>c.type==='text'),state.guild.channels.filter(c=>c.type==='voice'))});state.socket.on('guild:added',async guild=>{await loadGuilds();selectGuild(guild.id);toast(`${guild.name} foi adicionada às suas comunidades.`)});state.socket.on('profile:update',updated=>{const tile=document.querySelector(`.voice-person[data-user-id="${CSS.escape(updated.id)}"]`);if(tile){tile.querySelector('.voice-person-name').textContent=updated.displayName;tile.querySelector('.avatar').innerHTML=updated.avatar?`<img src="${escapeHtml(updated.avatar)}" alt="">`:escapeHtml(initials(updated.displayName))}for(const channels of Object.values(state.voiceRoster))for(const participants of Object.values(channels)){const participant=participants.find(p=>p.id===updated.id);if(participant)Object.assign(participant,updated)}if(state.guild)renderChannels(state.guild.channels.filter(c=>c.type==='text'),state.guild.channels.filter(c=>c.type==='voice'));state.members=state.members.map(m=>m.id===updated.id?{...m,...updated}:m);if(state.members.length)renderMembers();state.friends=state.friends.map(f=>f.user.id===updated.id?{...f,user:{...f.user,...updated}}:f);renderFriends();if(updated.id===state.user.id){state.user=updated;renderOwnProfile()}});state.socket.on('connect',()=>state.guilds.forEach(g=>state.socket.emit('subscribe:guild',g.id)));state.socket.on('connect_error',()=>toast('Conexão em tempo real indisponível.'));wireRealtime();await loadGuilds();await loadDms();await loadFriends()}
function wireRealtime(){const s=state.socket;s.on('message:new',m=>{if(state.channel?.id===m.channelId)appendMessage(m)});s.on('message:edit',m=>{const row=document.querySelector(`[data-message="${CSS.escape(m.id)}"] .message-text`);if(row)row.textContent=m.text});s.on('message:delete',m=>document.querySelector(`[data-message="${CSS.escape(m.id)}"]`)?.remove());s.on('message:reactions',m=>{const row=document.querySelector(`[data-message="${CSS.escape(m.id)}"] .message-tools`);if(row)renderReactions(row,m.reactions)});s.on('dm:new',m=>{if(state.dm?.id===m.dmId)appendMessage(m)});s.on('voice-video-mode',({userId,mode})=>{const tile=document.querySelector(`#voiceGrid [data-user-id="${CSS.escape(userId)}"]`);tile?.classList.toggle('screen-share',mode==='screen')});s.on('typing',t=>{if(t.channelId===state.channel?.id||t.dmId===state.dm?.id){$('#typingLine').textContent=`${t.user.displayName} está digitando...`;clearTimeout(wireRealtime.typing);wireRealtime.typing=setTimeout(()=>$('#typingLine').textContent='',1800)}})}
async function loadGuilds(){state.guilds=await api('/api/guilds');state.guilds.forEach(g=>state.socket?.emit('subscribe:guild',g.id));renderGuildRail();if(state.guild&&!state.guilds.some(g=>g.id===state.guild.id))state.guild=null;if(!state.guild&&state.guilds.length)selectGuild(state.guilds[0].id);else if(!state.guild)showWelcome()}
function renderGuildRail(){const rail=$('#guildRail');rail.replaceChildren();for(const g of state.guilds){const b=document.createElement('button');b.className=`guild-icon ${state.guild?.id===g.id?'active':''}`;b.title=g.name;b.setAttribute('aria-label',g.name);b.setAttribute('aria-pressed',String(state.guild?.id===g.id));b.textContent=initials(g.name).slice(0,1);b.addEventListener('click',()=>selectGuild(g.id));rail.append(b)}}
function renderGuildCover(guild=state.guild){const image=$('#communityCoverImage');if(!image)return;image.classList.toggle('hidden',!guild?.cover);if(guild?.cover)image.src=guild.cover;else image.removeAttribute('src')}
async function selectGuild(guildId){if(state.dm)state.dm=null;state.guild=state.guilds.find(g=>g.id===guildId)||null;if(!state.guild)return;renderGuildRail();$('#guildName').textContent='Comunidade';$('#communityCardName').textContent=state.guild.name;renderGuildCover();$('#communityCard').classList.remove('hidden');$('#editGuildBtn').classList.toggle('hidden',!['owner','admin'].includes(state.guild.role));$('#inviteBtn').disabled=false;$('#membersToggle').disabled=false;$('#homeBtn').classList.remove('active');$('#layout').classList.add('community-mode');$('#layout').classList.remove('menu-open','dm-mode');$('#mobileMenu').setAttribute('aria-expanded','false');$('#dmHeaderAvatar').classList.add('hidden');const text=state.guild.channels.filter(c=>c.type==='text'),voice=state.guild.channels.filter(c=>c.type==='voice');renderChannels(text,voice);await loadMembers();if(state.channel&&state.channel.guildId===guildId){selectChannel(state.channel.id)}else if(text.length)selectChannel(text[0].id);else showWelcome()}
function renderChannels(text,voice){const draw=(target,channels)=>{const wrap=$(target);wrap.replaceChildren();for(const c of channels){const active=c.type==='voice'?state.voice?.channel.id===c.id:state.channel?.id===c.id;const entry=document.createElement('div');entry.className=c.type==='voice'?'voice-channel-entry':'channel-entry';const b=document.createElement('button');b.className=`channel-link ${active?'active':''}`;b.innerHTML=`<span class="symbol">${lucide(c.type==='voice'?'volume':'hash')}</span><span class="channel-name">${escapeHtml(c.name)}</span>`;b.addEventListener('click',()=>c.type==='voice'?joinVoice(c):selectChannel(c.id));entry.append(b);if(c.type==='voice'){const participants=state.voiceRoster[state.guild?.id]?.[c.id]||[];const count=document.createElement('span');count.className='voice-channel-count';count.textContent=String(participants.length).padStart(2,'0')+ '/08';b.append(count);if(participants.length){const people=document.createElement('div');people.className='voice-channel-people';people.setAttribute('aria-label',`${participants.length} ${participants.length===1?'pessoa conectada':'pessoas conectadas'}`);participants.slice(0,6).forEach(person=>{const icon=document.createElement('button');icon.type='button';icon.className='voice-channel-avatar';icon.title=person.displayName||person.username;icon.setAttribute('aria-label',`Ver perfil de ${person.displayName||person.username}`);if(person.avatar){const img=document.createElement('img');img.src=person.avatar;img.alt='';icon.append(img)}else icon.textContent=initials(person.displayName||person.username);icon.addEventListener('click',()=>showUserCard(person));people.append(icon)});if(participants.length>6){const more=document.createElement('span');more.className='voice-channel-more';more.textContent=`+${participants.length-6}`;people.append(more)}entry.append(people)}}wrap.append(entry)}};draw('#textChannels',text);draw('#voiceChannels',voice)}
async function loadMembers(){if(!state.guild)return;try{state.members=await api(`/api/guilds/${state.guild.id}/members`);renderMembers()}catch{state.members=[];renderMembers()}}
function roleLabel(role){return({owner:'dono',admin:'administrador',member:'membro'})[role]||'membro'}
function renderMembers(){const root=$('#memberList');root.replaceChildren();$('#memberCount').textContent=String(state.members.length);if(!state.members.length){root.innerHTML='<p class="members-empty">Os membros aparecerão aqui.</p>';return}const groups=[['ONLINE',state.members.filter(m=>m.state==='online')],['OFFLINE',state.members.filter(m=>m.state!=='online')]];for(const [title,members] of groups){if(!members.length)continue;const h=document.createElement('div');h.className='member-group';h.textContent=`${title} — ${members.length}`;root.append(h);members.forEach(m=>{const row=document.createElement('button');row.type='button';row.className='member-item';row.innerHTML=`${avatar(m,m.state==='online')}<span class="member-label">${escapeHtml(m.displayName)}${m.role==='owner'?' <span aria-label="dono">♛</span>':''}<small>@${escapeHtml(m.username)}</small></span>`;row.title=`Clique na foto para opções ou no nome para abrir conversa · ${roleLabel(m.role)}`;row.addEventListener('click',event=>event.target.closest('.avatar')?showUserCard(m):openDmWithUser(m));root.append(row)})}}
function updatePresence(p){const m=state.members.find(x=>x.id===p.userId);if(m){m.state=p.state;renderMembers()}state.friends=state.friends.map(row=>row.user.id===p.userId?{...row,user:{...row.user,state:p.state}}:row);if(state.dmList)renderDms(state.dmList);renderFriends();renderFriendsHome()}
function showWelcome(){state.channel=null;state.dm=null;closeComposerEmoji();state.search='';$('#searchInput').value='';$('#searchInput').classList.add('hidden');$('#searchToggle').setAttribute('aria-expanded','false');$('#searchEmpty').classList.add('hidden');$('#welcome').classList.remove('hidden');$('#friendHome').classList.add('hidden');$('#messages').classList.add('hidden');$('#composer').classList.add('hidden');$('#conversationTitle').textContent=state.guild?.name||'Início';$('#conversationTopic').textContent='Escolha um canal ou comece uma conversa.';$('#channelSymbol').textContent='◈';$('#inviteBtn').disabled=!state.guild;$('#membersToggle').disabled=!state.guild;$('#membersPanel').classList.add('hidden');$('#membersToggle').setAttribute('aria-pressed','false');if(!state.guild){closeInline();$('#layout').classList.remove('menu-open','dm-mode');$('#mobileMenu').setAttribute('aria-expanded','false');$('#guildName').textContent='Mensagens diretas';$('#communityCard').classList.add('hidden');$('#textChannels').replaceChildren();$('#voiceChannels').replaceChildren();$('#homeBtn').classList.add('active');$('#homeTabs').classList.remove('hidden');$('#friendsTab').classList.remove('active');$('#dmsTab').classList.add('active');renderGuildRail()}else $('#homeTabs').classList.add('hidden')}
async function selectChannel(channelId){const channel=state.guild?.channels.find(c=>c.id===channelId);if(!channel)return;state.channel=channel;state.dm=null;$('#layout').classList.remove('dm-mode');$('#homeTabs').classList.add('hidden');$('#friendHome').classList.add('hidden');state.search='';$('#searchInput').value='';$('#searchInput').classList.add('hidden');$('#searchToggle').setAttribute('aria-expanded','false');$('#searchEmpty').classList.add('hidden');$('#welcome').classList.add('hidden');$('#messages').classList.remove('hidden');$('#composer').classList.remove('hidden');$('#conversationTitle').textContent=channel.name;$('#conversationTopic').textContent=channel.topic||`Canal de texto em ${state.guild.name}`;$('#channelSymbol').textContent=channel.type==='voice'?'◖':'#';$('#messageInput').placeholder=`Mensagem em #${channel.name}`;$('#layout').classList.remove('menu-open');$('#mobileMenu').setAttribute('aria-expanded','false');$('#homeBtn').classList.remove('active');renderChannels(state.guild.channels.filter(c=>c.type==='text'),state.guild.channels.filter(c=>c.type==='voice'));$('#inviteBtn').disabled=false;state.socket.emit('subscribe:channel',channel.id);try{const messages=await api(`/api/channels/${channel.id}/messages`);renderMessages(messages)}catch(e){toast(e.message)}}
function renderMessages(messages){const root=$('#messages');root.replaceChildren();if(!messages.length){root.innerHTML='<div class="empty-chat"><span class="empty-chat-icon">#</span><h2>Comece a conversa</h2><p>Envie a primeira mensagem deste canal.</p></div>';return}messages.forEach(appendMessage)}
function appendMessage(m){if((state.channel&&m.channelId!==state.channel.id)||(state.dm&&m.dmId!==state.dm.id))return;const root=$('#messages');if(root.querySelector('.welcome'))root.replaceChildren();if(root.querySelector(`[data-message="${CSS.escape(m.id)}"]`))return;const row=document.createElement('article');row.className=`message ${state.dm?'direct-message':''} ${state.dm&&m.user?.id===state.user?.id?'own-message':''}`;row.dataset.message=m.id;const dt=new Date(m.createdAt);const time=Number.isNaN(dt.getTime())?'':dt.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});row.innerHTML=`${avatar(m.user)}<div class="message-content"><div class="message-head"><strong>${escapeHtml(m.user?.displayName||m.user?.username)}</strong><time>${time}</time>${m.editedAt?'<span class="edited">(editada)</span>':''}<div class="message-actions">${m.user?.id===state.user.id?'<button data-edit>Editar</button>':''}<button data-react>Reagir</button>${m.user?.id===state.user.id?'<button data-delete>Excluir</button>':''}</div></div><p class="message-text">${escapeHtml(m.text)}</p><div class="message-tools"></div></div>`;row.querySelector('.avatar').addEventListener('click',()=>showUserCard(m.user));renderReactions(row.querySelector('.message-tools'),m.reactions||[]);row.querySelector('[data-edit]')?.addEventListener('click',()=>editMessage(m));row.querySelector('[data-delete]')?.addEventListener('click',()=>deleteMessage(m.id));row.querySelector('[data-react]')?.addEventListener('click',e=>reactMessage(m.id,e.currentTarget));root.append(row);root.scrollTop=root.scrollHeight}
function renderReactions(root,reactions){root.replaceChildren();const counts=new Map();for(const r of reactions||[])counts.set(r.emoji,[...(counts.get(r.emoji)||[]),r]);for(const [emoji,items] of counts){const b=document.createElement('button');b.className=`reaction ${items.some(x=>x.userId===state.user.id)?'mine':''}`;b.textContent=`${emoji} ${items.length}`;b.addEventListener('click',()=>toggleReaction(items[0].messageId,emoji));root.append(b)}}
function closeComposerEmoji(){const picker=$('#composerEmojiPicker'),toggle=$('#emojiToggle');picker?.classList.add('hidden');toggle?.setAttribute('aria-expanded','false')}
function setComposerEmoji(emoji){const input=$('#messageInput'),start=input.selectionStart,end=input.selectionEnd;input.setRangeText(emoji,start,end,'end');input.focus();input.dispatchEvent(new Event('input',{bubbles:true}));closeComposerEmoji()}
$('#composerEmojiPicker').replaceChildren(...['😀','😂','🥹','😍','😎','😭','🤔','👏','🙌','❤️','🔥','🎮'].map(emoji=>{const button=document.createElement('button');button.type='button';button.className='composer-emoji';button.textContent=emoji;button.title=`Inserir ${emoji}`;button.addEventListener('click',()=>setComposerEmoji(emoji));return button}));
$('#emojiToggle').addEventListener('click',()=>{const picker=$('#composerEmojiPicker'),open=picker.classList.toggle('hidden')===false;$('#emojiToggle').setAttribute('aria-expanded',String(open));if(open)$('#messageInput').focus()});
document.addEventListener('click',e=>{if(!e.target.closest('#composerEmojiPicker,#emojiToggle'))closeComposerEmoji();if(!e.target.closest('.message-actions,.emoji-picker'))document.querySelectorAll('.message-tools .emoji-picker').forEach(picker=>picker.remove())});
function editMessage(m){const row=document.querySelector(`[data-message="${CSS.escape(m.id)}"]`),content=row?.querySelector('.message-content'),textEl=row?.querySelector('.message-text');if(!content||!textEl||content.querySelector('.edit-inline'))return;const editor=document.createElement('div');editor.className='edit-inline';editor.innerHTML=`<textarea maxlength="2000"></textarea><div><button type="button" class="inline-cancel">Cancelar</button><button type="button" class="inline-submit">Salvar</button></div>`;const area=editor.querySelector('textarea');area.value=m.text;textEl.replaceWith(editor);area.focus();editor.querySelector('.inline-cancel').onclick=()=>{editor.replaceWith(textEl)};editor.querySelector('.inline-submit').onclick=async()=>{if(!area.value.trim())return;try{const updated=await api(`/api/messages/${m.id}`,{method:'PATCH',body:{text:area.value}});const next=document.createElement('p');next.className='message-text';next.textContent=updated.text;editor.replaceWith(next);if(!row.querySelector('.edited')){const tag=document.createElement('span');tag.className='edited';tag.textContent='(editada)';row.querySelector('.message-head time')?.after(tag)}}catch(e){toast(e.message)}}}
function deleteMessage(messageId){const row=document.querySelector(`[data-message="${CSS.escape(messageId)}"]`),content=row?.querySelector('.message-content');if(!content||content.querySelector('.delete-inline'))return;const confirmRow=document.createElement('div');confirmRow.className='delete-inline';confirmRow.innerHTML='<span>Excluir esta mensagem e seus anexos?</span><button type="button" class="inline-cancel">Cancelar</button><button type="button" class="delete-confirm">Excluir</button>';content.append(confirmRow);confirmRow.querySelector('.inline-cancel').onclick=()=>confirmRow.remove();confirmRow.querySelector('.delete-confirm').onclick=async()=>{const button=confirmRow.querySelector('.delete-confirm');button.disabled=true;try{await api(`/api/messages/${messageId}`,{method:'DELETE'});row.remove()}catch(e){button.disabled=false;toast(e.message)}}}
function reactMessage(messageId,button){const root=button.closest('.message-content').querySelector('.message-tools');if(root.querySelector('.emoji-picker'))return;const picker=document.createElement('div');picker.className='emoji-picker';for(const emoji of ['❤️','👍','😂','🔥','🎮']){const b=document.createElement('button');b.type='button';b.textContent=emoji;b.title=`Reagir com ${emoji}`;b.onclick=()=>{picker.remove();toggleReaction(messageId,emoji)};picker.append(b)}root.append(picker)}
async function toggleReaction(messageId,emoji){try{await api(`/api/messages/${messageId}/reactions`,{method:'POST',body:{emoji}})}catch(e){toast(e.message)}}
$('#composer').addEventListener('submit',async e=>{e.preventDefault();const input=$('#messageInput'),text=input.value.trim();if(!text)return;try{if(state.channel)await api(`/api/channels/${state.channel.id}/messages`,{method:'POST',body:{text}});else if(state.dm)await api(`/api/dms/${state.dm.id}/messages`,{method:'POST',body:{text}});input.value='';input.style.height='auto'}catch(e){toast(e.message)}});
$('#messageInput').addEventListener('input',e=>{e.target.style.height='auto';e.target.style.height=`${Math.min(e.target.scrollHeight,140)}px`;if(state.channel)state.socket.emit('typing',{channelId:state.channel.id});if(state.dm)state.socket.emit('typing',{dmId:state.dm.id})});
$('#messageInput').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#composer').requestSubmit()}});
function openInline(title,placeholder,label,handler,fieldLabel='Nome',prompt=''){const form=$('#inlineAction'),input=$('#inlineInput'),field=$('#inlineFieldLabel');$('#inlineTitle').textContent=title;input.placeholder=placeholder;input.setAttribute('aria-label',fieldLabel||title);field.firstChild.textContent=fieldLabel||'Nome';field.classList.toggle('hidden',fieldLabel===null);input.classList.toggle('hidden',fieldLabel===null);$('#inlinePrompt').textContent=prompt;$('#inlinePrompt').classList.toggle('hidden',!prompt);form.querySelector('.inline-submit').textContent=label;form._submitAction=handler;$('#inlineError').textContent='';input.value='';$('#actionDialog').showModal();if(fieldLabel!==null)input.focus()}
function closeInline(){const form=$('#inlineAction');if($('#actionDialog').open)$('#actionDialog').close();form.reset();form._submitAction=null;$('#inlineError').textContent=''}
$('#inlineAction').addEventListener('submit',async e=>{e.preventDefault();const value=$('#inlineInput').value.trim();if(!$('#inlineFieldLabel').classList.contains('hidden')&&!value)return;try{const done=await $('#inlineAction')._submitAction?.(value);if(done!==false)closeInline()}catch(err){$('#inlineError').textContent=err.message}});$('#inlineCancel').addEventListener('click',closeInline);$('#inlineClose').addEventListener('click',closeInline);
function createGuild(){openInline('Nova comunidade','Ex.: Galera do bairro','Criar comunidade',async name=>{try{const g=await api('/api/guilds',{method:'POST',body:{name}});state.guilds.push(g);state.guild=g;renderGuildRail();await selectGuild(g.id);return true}catch(e){$('#inlineError').textContent=e.message;return false}},'Nome da comunidade')}
function editGuild(){if(!state.guild||!['owner','admin'].includes(state.guild.role))return;$('#guildEditForm').elements.name.value=state.guild.name;$('#guildCoverInput').value='';state.guildCoverDraft=state.guild.cover||'';const preview=$('#guildCoverPreview');preview.classList.toggle('hidden',!state.guildCoverDraft);if(state.guildCoverDraft)preview.querySelector('img').src=state.guildCoverDraft;$('#guildEditError').textContent='';$('#guildEditDialog').showModal()}
$('#editGuildBtn').addEventListener('click',editGuild);$('#guildEditClose').addEventListener('click',()=>$('#guildEditDialog').close());$('#guildEditCancel').addEventListener('click',()=>$('#guildEditDialog').close());$('#guildEditForm').addEventListener('submit',async event=>{event.preventDefault();if(!state.guild)return;try{const guild=await api(`/api/guilds/${state.guild.id}`,{method:'PATCH',body:{name:event.currentTarget.elements.name.value.trim(),cover:state.guildCoverDraft??state.guild.cover??''}});Object.assign(state.guild,guild);const stored=state.guilds.find(item=>item.id===guild.id);if(stored)Object.assign(stored,guild);$('#guildName').textContent='Comunidade';$('#communityCardName').textContent=guild.name;renderGuildCover(guild);renderGuildRail();$('#guildEditDialog').close();toast('Comunidade atualizada.')}catch(error){$('#guildEditError').textContent=error.message}});
$('#guildCoverInput').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>5_000_000){$('#guildEditError').textContent='Escolha uma imagem PNG, JPG ou WebP de até 5 MB.';event.target.value='';return}try{const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=dataUrl});const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d'),ratio=Math.max(1200/image.width,450/image.height);canvas.width=1200;canvas.height=450;ctx.drawImage(image,(1200-image.width*ratio)/2,(450-image.height*ratio)/2,image.width*ratio,image.height*ratio);const cover=canvas.toDataURL('image/jpeg',.78);if(cover.length>900_000)throw new Error('A imagem ficou grande demais. Escolha uma foto menor.');state.guildCoverDraft=cover;$('#guildCoverPreview').classList.remove('hidden');$('#guildCoverPreview img').src=cover;$('#guildEditError').textContent=''}catch(error){$('#guildEditError').textContent=error.message||'Não consegui carregar essa imagem.'}});
$('#guildCoverRemove').addEventListener('click',()=>{state.guildCoverDraft='';$('#guildCoverInput').value='';$('#guildCoverPreview').classList.add('hidden')});
function createChannel(type){if(!state.guild)return toast('Escolha uma comunidade primeiro.');openInline(type==='voice'?'Nova sala de voz':'Novo canal de texto','Ex.: conversas',type==='voice'?'Criar sala':'Criar canal',async name=>{try{const c=await api(`/api/guilds/${state.guild.id}/channels`,{method:'POST',body:{name,type}});state.guild.channels.push(c);renderChannels(state.guild.channels.filter(x=>x.type==='text'),state.guild.channels.filter(x=>x.type==='voice'));if(type==='text')selectChannel(c.id);return true}catch(e){$('#inlineError').textContent=e.message;return false}},type==='voice'?'Nome da sala':'Nome do canal')}
async function invite(){if(!state.guild)return;try{const result=await api(`/api/guilds/${state.guild.id}/invites`,{method:'POST',body:{}});const url=`${location.origin}/?invite=${encodeURIComponent(result.code)}`;try{await navigator.clipboard.writeText(url);toast('Convite copiado. Ele expira em 7 dias.')}catch{toast(`Copie este convite: ${url}`)}}catch(e){toast(e.message)}}
async function loadDms(){try{const list=await api('/api/dms');renderDms(list)}catch{}}
async function loadFriends(){try{state.friends=await api('/api/friends');renderFriends();if(state.dmList)renderDms(state.dmList);await loadNotifications()}catch{}}
async function loadNotifications(){try{state.notifications=await api('/api/notifications');renderNotifications();if(state.socket&&!state.notificationListener){state.notificationListener=true;state.socket.on('notification:new',item=>{state.notifications.unshift(item);state.notifications=state.notifications.slice(0,60);renderNotifications();playUiSound('notify');toast(item.title)})}}catch{}}
function renderNotifications(){const unread=state.notifications.filter(item=>!item.readAt).length,badge=$('#notificationCount'),root=$('#notificationList');badge.textContent=unread>99?'99+':String(unread);badge.classList.toggle('hidden',!unread);root.replaceChildren();if(!state.notifications.length){const empty=document.createElement('p');empty.className='notification-empty';empty.textContent='Você está em dia. Nenhuma notificação por enquanto.';root.append(empty);return}for(const item of state.notifications){const button=document.createElement('button');button.type='button';button.className=`notification-item ${item.readAt?'':'unread'}`;button.dataset.notificationId=item.id;button.innerHTML=`<span class="notification-dot"></span><span><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.message)}</small><time>${new Date(item.createdAt).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}</time></span>`;button.addEventListener('click',()=>openNotification(item));root.append(button)}}
async function openNotification(item){try{if(!item.readAt){await api(`/api/notifications/${encodeURIComponent(item.id)}/read`,{method:'PATCH',body:{}});item.readAt=Date.now();renderNotifications()}$('#notificationPanel').classList.add('hidden');$('#notificationToggle').setAttribute('aria-expanded','false');if(item.metadata?.channelId&&item.metadata?.guildId){const guild=state.guilds.find(value=>value.id===item.metadata.guildId);if(guild){await selectGuild(guild.id);selectChannel(item.metadata.channelId)}}else if(item.metadata?.dmId){const conversations=await api('/api/dms'),dm=conversations.find(value=>value.id===item.metadata.dmId);if(dm)await openDm(dm.id,dm.users[0])}else if(item.type.startsWith('friend_'))await showFriendsHome();else if(item.metadata?.guildId){const guild=state.guilds.find(value=>value.id===item.metadata.guildId);if(guild)await selectGuild(guild.id)}}catch(error){toast(error.message)}}
$('#notificationToggle').addEventListener('click',()=>{const panel=$('#notificationPanel'),open=panel.classList.toggle('hidden')===false;$('#notificationToggle').setAttribute('aria-expanded',String(open))});
$('#notificationReadAll').addEventListener('click',async()=>{try{await api('/api/notifications/read-all',{method:'POST',body:{}});state.notifications.forEach(item=>item.readAt||=Date.now());renderNotifications()}catch(error){toast(error.message)}});
document.addEventListener('click',event=>{if(!event.target.closest('#notificationPanel,#notificationToggle')){$('#notificationPanel').classList.add('hidden');$('#notificationToggle').setAttribute('aria-expanded','false')}});
function renderFriends(){const root=$('#friendList');if(!root)return;root.replaceChildren();if(!state.friends.length){const empty=document.createElement('p');empty.className='friend-empty';empty.textContent='Adicione pessoas pelo nome de usuário.';root.append(empty);renderFriendsHome();return}for(const row of state.friends){const user=row.user,item=document.createElement('div');item.className='friend-row';item.append(Object.assign(document.createElement('span'),{className:'friend-avatar',innerHTML:avatar(user)}));item.querySelector('.friend-avatar').addEventListener('click',()=>showUserCard(user));const label=document.createElement('span');label.className='friend-label';label.innerHTML=`<strong>${escapeHtml(user.displayName)}</strong><small>@${escapeHtml(user.username)} · ${row.status==='accepted'?'Amigo':row.direction==='incoming'?'Pedido recebido':'Pendente'}</small>`;item.append(label);const actions=document.createElement('span');actions.className='friend-actions';if(row.status==='accepted'){const dm=document.createElement('button');dm.type='button';dm.textContent='Mensagem';dm.title='Abrir conversa';dm.onclick=()=>openDmWithUser(user);actions.append(dm);if(state.guild){const invite=document.createElement('button');invite.type='button';invite.textContent='＋';invite.title=`Adicionar ${user.displayName} a ${state.guild.name}`;invite.onclick=()=>inviteFriendToGuild(user);actions.append(invite)}}else if(row.direction==='incoming'){const accept=document.createElement('button');accept.type='button';accept.textContent='Aceitar';accept.onclick=async()=>{try{await api('/api/friends',{method:'POST',body:{userId:user.id}});await loadFriends();toast(`${user.displayName} agora é seu amigo.`)}catch(e){toast(e.message)}};actions.append(accept)}const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.title=row.status==='accepted'?'Remover amigo':'Cancelar pedido';remove.onclick=async()=>{try{await api(`/api/friends/${user.id}`,{method:'DELETE'});await loadFriends()}catch(e){toast(e.message)}};actions.append(remove);item.append(actions);root.append(item)}renderFriendsHome()}
function renderFriendsHome(){const root=$('#friendHomeList');if(!root)return;root.replaceChildren();if(!state.friends.length){root.innerHTML='<p class="friend-home-empty">Você ainda não tem amigos por aqui. Adicione alguém pelo nome de usuário.</p>';return}for(const row of state.friends){const user=row.user,item=document.createElement('div');item.className='friend-home-row';item.append(Object.assign(document.createElement('button'),{type:'button',className:'friend-home-avatar',innerHTML:avatar(user),title:`Ver perfil de ${user.displayName}`}));item.querySelector('.friend-home-avatar').addEventListener('click',()=>showUserCard(user));const label=document.createElement('span');label.innerHTML=`<strong>${escapeHtml(user.displayName)}</strong><small><i class="presence-dot ${user.state==='online'?'is-online':''}"></i>${user.state==='online'?'Online':'Offline'} · ${row.status==='accepted'?'Amigo':row.direction==='incoming'?'Pedido recebido':'Pedido enviado'}</small>`;item.append(label);const action=document.createElement('button');action.type='button';action.className=row.status==='accepted'?'friend-home-message':'friend-home-request';if(row.status==='accepted'){action.textContent='Mensagem';action.addEventListener('click',()=>openDmWithUser(user))}else if(row.direction==='incoming'){action.textContent='Aceitar';action.addEventListener('click',async()=>{try{await api('/api/friends',{method:'POST',body:{userId:user.id}});await loadFriends();toast(`${user.displayName} agora é seu amigo.`)}catch(error){toast(error.message)}})}else{action.textContent='Pendente';action.disabled=true}item.append(action);if(row.status==='accepted'){const invite=document.createElement('button');invite.type='button';invite.className='friend-home-invite';invite.textContent='Convidar';invite.title='Convidar para uma comunidade';invite.addEventListener('click',()=>inviteFriendToGuild(user));item.append(invite)}root.append(item)}}
async function inviteFriendToGuild(user){const choices=state.guilds.filter(g=>!g.members?.some(m=>m.userId===user.id));if(!choices.length){toast(state.guilds.length?'Esse amigo já está em todas as suas comunidades.':'Entre ou crie uma comunidade antes de convidar amigos.');return}let guild=state.guild&&choices.find(g=>g.id===state.guild.id);if(!guild&&choices.length===1)guild=choices[0];if(!guild){let dialog=$('#friendGuildInviteDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='friendGuildInviteDialog';dialog.className='profile-dialog';dialog.innerHTML='<form method="dialog"><header><div><p class="eyebrow">CONVITE</p><h2>Adicionar à comunidade</h2></div><button class="ghost" value="cancel" aria-label="Fechar">×</button></header><label>Escolha uma comunidade<select name="guild"></select></label><footer><button class="inline-cancel" value="cancel">Cancelar</button><button class="primary" value="confirm">Convidar</button></footer></form>';document.body.append(dialog)}const select=dialog.querySelector('select');select.replaceChildren(...choices.map(item=>new Option(item.name,item.id)));dialog.showModal();const result=await new Promise(resolve=>dialog.addEventListener('close',()=>resolve(dialog.returnValue),{once:true}));if(result!=='confirm')return;guild=choices.find(item=>item.id===select.value)}try{await api(`/api/guilds/${guild.id}/members`,{method:'POST',body:{userId:user.id}});if(state.guild?.id===guild.id)await loadMembers();toast(`${user.displayName} foi adicionado a ${guild.name}.`)}catch(e){toast(e.message)}}
function addFriend(){openInline('Adicionar amigo','Digite o @usuário','Enviar pedido',async value=>{const username=value.replace(/^@/,'').trim().toLowerCase();try{const users=await api(`/api/users/search?q=${encodeURIComponent(username)}`),user=users.find(u=>u.username===username);if(!user){$('#inlineError').textContent='Não encontrei esse usuário. Confira o nome e tente novamente.';return false}await api('/api/friends',{method:'POST',body:{userId:user.id}});await loadFriends();toast(`Pedido enviado para @${user.username}.`);return true}catch(e){$('#inlineError').textContent=e.message;return false}},'Nome de usuário')}
function renderOwnProfile(){if(!state.user)return;$('#myName').textContent=state.user.displayName;$('#myHandle').textContent=`@${state.user.username}`;$('#myAvatar').innerHTML=state.user.avatar?`<img src="${escapeHtml(state.user.avatar)}" alt="">`:escapeHtml(initials(state.user.displayName))}
function openProfile(){const form=$('#profileForm');form.elements.displayName.value=state.user.displayName;form.elements.username.value=state.user.username;form.elements.currentPassword.value='';form.elements.newPassword.value='';state.profileAvatar=state.user.avatar||'';$('#profilePhotoPreview').innerHTML=state.profileAvatar?`<img src="${escapeHtml(state.profileAvatar)}" alt="Prévia da foto">`:'Adicionar foto';$('#profileError').textContent='';$('#profileDialog').showModal()}
async function prepareAvatar(file){if(!file)return '';if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('Escolha uma imagem PNG, JPG ou WebP.');const url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Não foi possível ler a imagem.'));reader.readAsDataURL(file)});const img=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('Arquivo de imagem inválido.'));image.src=url});const canvas=document.createElement('canvas'),size=256;canvas.width=size;canvas.height=size;const ctx=canvas.getContext('2d'),crop=Math.min(img.width,img.height);ctx.drawImage(img,(img.width-crop)/2,(img.height-crop)/2,crop,crop,0,0,size,size);const result=canvas.toDataURL('image/webp',.78);if(result.length>90000)throw new Error('A foto ficou grande demais. Tente uma imagem menor.');return result}
