function renderDms(items){state.dmList=items;const root=$('#dmList');root.replaceChildren();items.forEach(dm=>{const user=dm.users[0];if(!user)return;user.state=state.friends.find(row=>row.user.id===user.id)?.user.state||user.state||'offline';const b=document.createElement('button');b.className=`dm-link ${state.dm?.id===dm.id?'active':''}`;b.innerHTML=`${avatar(user,user.state==='online')}<span class="dm-link-copy"><strong>${escapeHtml(user.displayName)}</strong><small><i class="presence-dot ${user.state==='online'?'is-online':''}"></i>@${escapeHtml(user.username)} · ${user.state==='online'?'Online':'Offline'}</small></span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5h11v11M19 5 5 19"/></svg>`;b.addEventListener('click',event=>event.target.closest('.avatar')?showUserCard(user):openDm(dm.id,user));root.append(b)})}
