async function acceptInvite(){const code=new URLSearchParams(location.search).get('invite');if(!code||!state.user)return;try{const g=await api(`/api/invites/${encodeURIComponent(code)}/join`,{method:'POST',body:{}});state.guilds=state.guilds.filter(x=>x.id!==g.id);state.guilds.push(g);history.replaceState({},'',location.pathname);selectGuild(g.id);toast(`Você entrou em ${g.name}.`)}catch(e){toast(e.message);history.replaceState({},'',location.pathname)}}
