async function joinVoice(channel){if(state.voice){if(state.voice.channel.id===channel.id){restoreCall();return}leaveCall()}try{const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true},video:false});const socket=state.socket,room=`brasa-${channel.id}`,peers=new Map();state.voice={channel,stream,socket,room,peers,muted:false,deafened:false,videoTrack:null,screenTrack:null};$('#voiceStage').classList.remove('hidden');$('#callDock').classList.add('hidden');$('#callTitle').textContent=channel.name;$('#callDockTitle').textContent=`Chamada em ${channel.name}`;setCallStatus('Entrando na sala…');$('#voiceGrid').replaceChildren();addVoicePerson('self',state.user.displayName,true,'Microfone ativo',state.user);socket.emit('voice-join',{room});socket.on('voice-peers',list=>{list.forEach(p=>makePeer(p.id,true,p.name,p.userId,p.avatar));setCallStatus('Conectado à sala',true)});socket.on('voice-peer-joined',p=>makePeer(p.id,false,p.name,p.userId,p.avatar));socket.on('voice-signal',async({from,data})=>{const peer=makePeer(from,false,'Participante');if(data.description){const pc=peer.pc,collision=data.description.type==='offer'&&(peer.makingOffer||pc.signalingState!=='stable');if(collision&&!peer.polite){peer.ignoreOffer=true;return}if(collision&&peer.polite)await pc.setLocalDescription({type:'rollback'});await pc.setRemoteDescription(data.description);for(const candidate of peer.pendingCandidates||[])await pc.addIceCandidate(candidate);peer.pendingCandidates=[];if(data.description.type==='offer'){await pc.setLocalDescription(await pc.createAnswer());socket.emit('voice-signal',{to:from,data:{description:pc.localDescription}})}}else if(data.candidate){try{if(peer.pc.remoteDescription)await peer.pc.addIceCandidate(data.candidate);else(peer.pendingCandidates||=[]).push(data.candidate)}catch{}}});socket.on('voice-peer-left',({id})=>{const p=peers.get(id);p?.pc.close();peers.delete(id);document.querySelector(`[data-peer="${CSS.escape(id)}"]`)?.remove();document.querySelector(`[data-audio="${CSS.escape(id)}"]`)?.remove();updateCallRoster()});socket.on('voice-error',e=>{setCallStatus(e.message,false,true);toast(e.message);leaveCall()});updateCallRoster()}catch(e){$('#voiceStage').classList.add('hidden');$('#callDock').classList.add('hidden');document.querySelectorAll('#voiceChannels .channel-link').forEach(item=>item.classList.remove('active'));toast(e.name==='NotAllowedError'?'Permita o microfone para entrar na sala.':e.name==='NotFoundError'?'Nenhum microfone foi encontrado. Conecte ou selecione um dispositivo.':'Não consegui acessar o microfone. Verifique as permissões do navegador.')}}
function addVoicePerson(id,name,self=false,status='Conectando áudio...',profile={}){const grid=$('#voiceGrid');let tile=grid.querySelector(`[data-peer="${CSS.escape(id)}"]`);if(!tile){tile=document.createElement('article');tile.className=`voice-person ${self?'self':'connecting'}`;tile.dataset.peer=id;tile.innerHTML=`<div class="avatar">${profile.avatar?`<img src="${escapeHtml(profile.avatar)}" alt="">`:escapeHtml(initials(name))}</div><strong class="voice-person-name"></strong><span class="voice-person-state"></span><span class="voice-person-badge"><span class="mic-state">♩</span><span>Microfone ativo</span></span><button class="video-expand" type="button" aria-label="Expandir vídeo" title="Expandir vídeo">⛶</button>${self?'<span class="you-tag">VOCÊ</span>':''}`;tile.querySelector('.video-expand').addEventListener('click',()=>toggleVideoExpand(tile));grid.append(tile)}tile.dataset.userId=profile.id||profile.userId||'';const avatarEl=tile.querySelector('.avatar');avatarEl.setAttribute('role','button');avatarEl.tabIndex=0;avatarEl.setAttribute('aria-label',`Ver perfil de ${name}`);const openProfile=()=>{const user=state.members.find(item=>item.id===tile.dataset.userId)||state.friends.find(item=>item.user.id===tile.dataset.userId)?.user||(self?state.user:null);if(user)showUserCard(user)};avatarEl.onclick=openProfile;avatarEl.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openProfile()}};tile.querySelector('.voice-person-name').textContent=name;tile.querySelector('.voice-person-state').textContent=status;updateCallRoster();if(self&&state.voice)watchSpeaking(state.voice.stream,tile);return tile}
function toggleVideoExpand(tile){const button=tile.querySelector('.video-expand');if(document.fullscreenElement===tile){document.exitFullscreen?.();return}if(tile.requestFullscreen){tile.requestFullscreen().catch(()=>{tile.classList.toggle('video-expanded');const expanded=tile.classList.contains('video-expanded');button?.setAttribute('aria-label',expanded?'Minimizar vídeo':'Expandir vídeo');button?.setAttribute('title',expanded?'Minimizar vídeo':'Expandir vídeo')})}else{tile.classList.toggle('video-expanded');const expanded=tile.classList.contains('video-expanded');button?.setAttribute('aria-label',expanded?'Minimizar vídeo':'Expandir vídeo');button?.setAttribute('title',expanded?'Minimizar vídeo':'Expandir vídeo')}}
document.addEventListener('fullscreenchange',()=>document.querySelectorAll('.voice-person').forEach(tile=>{const expanded=document.fullscreenElement===tile||tile.classList.contains('video-expanded'),button=tile.querySelector('.video-expand');if(button){button.textContent=expanded?'⤢':'⛶';button.title=expanded?'Minimizar vídeo':'Expandir vídeo';button.setAttribute('aria-label',button.title)}}));
function watchSpeaking(stream,tile){const v=state.voice,AudioCtx=window.AudioContext||window.webkitAudioContext;if(!v||!AudioCtx||!stream.getAudioTracks().length)return;try{const context=new AudioCtx(),analyser=context.createAnalyser();analyser.fftSize=512;const source=context.createMediaStreamSource(stream);source.connect(analyser);const samples=new Uint8Array(analyser.fftSize),monitor={context,frame:0};v.monitors??=[];v.monitors.push(monitor);const measure=()=>{if(!state.voice||state.voice!==v||!tile.isConnected)return;analyser.getByteTimeDomainData(samples);let energy=0;for(const sample of samples){const n=(sample-128)/128;energy+=n*n}tile.classList.toggle('speaking',Math.sqrt(energy/samples.length)>.055);monitor.frame=requestAnimationFrame(measure)};context.resume().then(measure).catch(()=>{})}catch{}}
function setCallStatus(text,connected=false,error=false){const el=$('#callStatus');el.className=`voice-status${connected?' connected':''}${error?' error':''}`;el.innerHTML=`<i></i> ${escapeHtml(text)}`}
function makePeer(id,initiator,name='Participante',userId='',avatarUrl=''){const v=state.voice;if(!v)return null;if(v.peers.has(id)){const found=v.peers.get(id);if(name&&name!=='Participante'){found.name=name;const n=document.querySelector(`[data-peer="${CSS.escape(id)}"] .voice-person-name`);if(n)n.textContent=name}return found}const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});const peer={pc,name,userId,polite:state.socket.id.localeCompare(id)>0,makingOffer:false,ignoreOffer:false};v.peers.set(id,peer);const tile=addVoicePerson(id,name,false,'Conectando áudio...',{userId,avatar:avatarUrl});pc.onicecandidate=e=>e.candidate&&v.socket.emit('voice-signal',{to:id,data:{candidate:e.candidate}});pc.onnegotiationneeded=async()=>{try{peer.makingOffer=true;await pc.setLocalDescription(await pc.createOffer());v.socket.emit('voice-signal',{to:id,data:{description:pc.localDescription}})}catch{}finally{peer.makingOffer=false}};pc.ontrack=e=>{if(e.track.kind==='video'){const video=document.createElement('video');video.autoplay=true;video.playsInline=true;video.muted=true;video.srcObject=e.streams[0];tile.classList.add('has-video');tile.querySelector('video')?.remove();tile.prepend(video);video.play().catch(()=>{});return}let audio=document.querySelector(`[data-audio="${CSS.escape(id)}"]`);if(!audio){audio=document.createElement('audio');audio.dataset.audio=id;audio.autoplay=true;audio.className='voice-audio';document.body.append(audio)}audio.srcObject=e.streams[0];watchSpeaking(e.streams[0],tile);audio.muted=v.deafened;audio.play().catch(()=>{})};pc.onconnectionstatechange=()=>{const status=pc.connectionState==='connected'?'Conectado':pc.connectionState==='connecting'?'Conectando áudio...':pc.connectionState==='disconnected'?'Reconectando...':'Falha na conexão';tile.querySelector('.voice-person-state').textContent=status;tile.classList.toggle('connecting',pc.connectionState!=='connected');if(pc.connectionState==='connected')setCallStatus('Conectado à sala',true);if(pc.connectionState==='failed'){v.peers.delete(id);document.querySelector(`[data-audio="${CSS.escape(id)}"]`)?.remove();tile.remove();updateCallRoster()}};v.stream.getTracks().forEach(t=>pc.addTrack(t,v.stream));return peer}
function updateCallRoster(){const v=state.voice;if(!v)return;const count=v.peers.size+1,label=`${count} ${count===1?'participante':'participantes'}`;const names=[...document.querySelectorAll('#voiceGrid .voice-person-name')].map(x=>x.textContent).join(', ');$('#callRoster').textContent=names?`${label}: ${names}`:label;$('#callDockCount').textContent=label}
function minimizeCall(){if(!state.voice)return;$('#voiceStage').classList.add('hidden');$('#callDock').classList.remove('hidden')}
function restoreCall(){if(!state.voice)return;$('#voiceStage').classList.remove('hidden');$('#callDock').classList.add('hidden')}
$('#muteBtn').addEventListener('click',()=>{const v=state.voice;if(!v)return;v.muted=!v.muted;v.stream.getAudioTracks().forEach(t=>t.enabled=!v.muted&&!v.deafened);$('#muteBtn').classList.toggle('off',v.muted);$('#muteBtn').setAttribute('aria-pressed',String(v.muted));$('#muteBtn').querySelector('small').textContent=v.muted?'Ativar microfone':'Microfone';$('#muteBtn').title=v.muted?'Ativar microfone':'Silenciar microfone';const self=$('#voiceGrid [data-peer="self"]');self?.querySelector('.mic-state').classList.toggle('muted',v.muted);self?.querySelector('.voice-person-state')&&(self.querySelector('.voice-person-state').textContent=v.muted?'Microfone silenciado':'Seu microfone está ativo')});
$('#deafenBtn').addEventListener('click',()=>{const v=state.voice;if(!v)return;v.deafened=!v.deafened;v.stream.getAudioTracks().forEach(t=>t.enabled=!v.deafened&&!v.muted);document.querySelectorAll('audio[data-audio]').forEach(a=>a.muted=v.deafened);$('#deafenBtn').classList.toggle('off',v.deafened);$('#deafenBtn').setAttribute('aria-pressed',String(v.deafened));$('#deafenBtn').querySelector('small').textContent=v.deafened?'Ativar áudio':'Áudio';$('#deafenBtn').title=v.deafened?'Ativar áudio de entrada':'Desativar áudio de entrada';const self=$('#voiceGrid [data-peer="self"]');self?.querySelector('.mic-state').classList.toggle('muted',v.deafened||v.muted);if(v.deafened&&!v.muted)$('#muteBtn').querySelector('small').textContent='Microfone';if(!v.deafened&&v.muted)$('#muteBtn').querySelector('small').textContent='Ativar microfone'});
function setLocalVideoPreview(){const v=state.voice,tile=$('#voiceGrid [data-peer="self"]');if(!v||!tile)return;tile.querySelector('video')?.remove();const track=v.videoTrack||v.screenTrack;if(!track){tile.classList.remove('has-video','screen-share');return}const video=document.createElement('video');video.autoplay=true;video.playsInline=true;video.muted=true;video.srcObject=v.stream;tile.classList.add('has-video');tile.classList.toggle('screen-share',Boolean(v.screenTrack));tile.prepend(video);video.play().catch(()=>{})}
function addVideoTrack(track,key){const v=state.voice;if(!v)return;v[key]=track;v.stream.addTrack(track);for(const peer of v.peers.values())peer.pc.addTrack(track,v.stream);setLocalVideoPreview();v.socket.emit('voice-video-mode',{mode:key==='screenTrack'?'screen':'camera'});const btn=key==='videoTrack'?$('#videoBtn'):$('#shareBtn');btn.classList.add('off');btn.setAttribute('aria-pressed','true');btn.querySelector('small').textContent=key==='videoTrack'?'Parar câmera':'Parar tela';btn.title=key==='videoTrack'?'Desativar câmera':'Parar compartilhamento';updateSelfState()}
function removeVideoTrack(key){const v=state.voice,track=v?.[key];if(!track)return;v[key]=null;v.stream.removeTrack(track);for(const peer of v.peers.values())peer.pc.getSenders().filter(sender=>sender.track===track).forEach(sender=>peer.pc.removeTrack(sender));track.stop();setLocalVideoPreview();v.socket.emit('voice-video-mode',{mode:v.screenTrack?'screen':v.videoTrack?'camera':'none'});const btn=key==='videoTrack'?$('#videoBtn'):$('#shareBtn');btn.classList.remove('off');btn.setAttribute('aria-pressed','false');btn.querySelector('small').textContent=key==='videoTrack'?'Câmera':'Tela';btn.title=key==='videoTrack'?'Ativar câmera':'Compartilhar tela';updateSelfState()}
function updateSelfState(){const v=state.voice,tile=$('#voiceGrid [data-peer="self"]');if(!v||!tile)return;const quiet=v.muted||v.deafened;tile.querySelector('.mic-state').classList.toggle('muted',quiet);tile.querySelector('.voice-person-state').textContent=v.deafened?'Áudio desativado':v.muted?'Microfone silenciado':v.screenTrack?'Compartilhando a tela':v.videoTrack?'Câmera ligada':'Microfone ativo'}
$('#videoBtn').addEventListener('click',async()=>{const v=state.voice;if(!v)return;if(v.videoTrack){removeVideoTrack('videoTrack');return}if(v.screenTrack)removeVideoTrack('screenTrack');try{const stream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720},frameRate:{ideal:24,max:30}},audio:false});const track=stream.getVideoTracks()[0];addVideoTrack(track,'videoTrack');track.onended=()=>{if(state.voice?.videoTrack===track)removeVideoTrack('videoTrack')}}catch(e){toast(e.name==='NotAllowedError'?'Permita o acesso à câmera para ativar o vídeo.':'Não foi possível iniciar a câmera.')}});
$('#shareBtn').addEventListener('click',async()=>{const v=state.voice;if(!v)return;if(v.screenTrack){removeVideoTrack('screenTrack');return}if(v.videoTrack)removeVideoTrack('videoTrack');try{const stream=await navigator.mediaDevices.getDisplayMedia({video:{frameRate:{ideal:30}},audio:false});const track=stream.getVideoTracks()[0],width=Number(document.getElementById('screenQuality').value);try{await track.applyConstraints({width:{ideal:width},height:{ideal:Math.round(width*9/16)},frameRate:{ideal:30,max:30}})}catch{}addVideoTrack(track,'screenTrack');track.onended=()=>{if(state.voice?.screenTrack===track)removeVideoTrack('screenTrack')}}catch(e){if(e.name!=='NotAllowedError')toast('Não foi possível compartilhar a tela.')}});
async function setScreenResolution(){const track=state.voice?.screenTrack;if(!track)return;const width=Number($('#screenQuality').value),height=Math.round(width*9/16);try{await track.applyConstraints({width:{ideal:width},height:{ideal:height},frameRate:{ideal:30,max:30}});toast(`Transmissão ajustada para até ${width}p.`)}catch{toast('O navegador não permitiu alterar a resolução desta transmissão.')}}
$('#screenQuality').addEventListener('change',setScreenResolution);
function leaveCall(){const v=state.voice;if(!v)return;v.socket.emit('voice-leave');v.peers.forEach(p=>p.pc.close());v.peers.clear();v.monitors?.forEach(m=>{cancelAnimationFrame(m.frame);m.context.close()});v.stream.getTracks().forEach(t=>t.stop());document.querySelectorAll('audio[data-audio]').forEach(a=>a.remove());v.socket.off('voice-peers');v.socket.off('voice-peer-joined');v.socket.off('voice-signal');v.socket.off('voice-peer-left');v.socket.off('voice-error');state.voice=null;$('#voiceStage').classList.add('hidden');$('#callDock').classList.add('hidden');$('#voiceGrid').replaceChildren();for(const [id,label,title] of [['muteBtn','Microfone','Silenciar microfone'],['deafenBtn','Áudio','Desativar áudio de entrada'],['videoBtn','Câmera','Ativar câmera'],['shareBtn','Tela','Compartilhar tela']]){$(`#${id}`).classList.remove('off');$(`#${id}`).setAttribute('aria-pressed','false');$(`#${id} small`).textContent=label;$('#'+id).title=title}document.querySelectorAll('#voiceChannels .channel-link').forEach(item=>item.classList.remove('active'))}
$('#leaveCall').addEventListener('click',leaveCall);

